<script setup lang="ts">import{onMounted,ref}from'vue';import http from'../api/http';const rows=ref<any[]>([]);async function load(){const{data}=await http.get('/workflow/tasks/pending');rows.value=data.data||[]}async function act(row:any,action:'approve'|'reject'){const opinion=action==='reject'?prompt('请输入驳回原因')||'':'同意';if(action==='reject'&&!opinion)return;await http.post(`/workflow/tasks/${row.id}/${action}`,{opinion});await load()}onMounted(load)</script>
<template><el-card><template #header>我的待办</template><el-table :data="rows"><el-table-column prop="instanceNo" label="流程编号"/><el-table-column prop="bizType" label="业务类型"/><el-table-column prop="bizNo" label="业务单号"/><el-table-column prop="nodeName" label="当前节点"/><el-table-column label="操作" width="170"><template #default="{row}"><el-button type="success" size="small" @click="act(row,'approve')">通过</el-button><el-button type="danger" size="small" @click="act(row,'reject')">驳回</el-button></template></el-table-column></el-table></el-card></template>
